const refusal = (e) => {
  const msg = String(e.message || '');
  let body = null;
  try { body = JSON.parse(msg.slice(msg.indexOf(' - ') + 3)); if (typeof body === 'string') body = JSON.parse(body); } catch (_) {}
  return { status: Number(e.status || e.httpCode || msg.slice(0, 3)) || 0, code: body?.error?.code || '', text: body?.error?.message || msg, unlock: body?.error?.unlock?.url || '', limit: body?.error?.details?.limit || null };
};
const count = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const keyError = () => new Error(`Arcmira didn't accept the API key. Pick a Header Auth credential named Authorization with the value "Bearer <your key>" in "Check the plan's dates", "List channel videos from Arcmira" and "Get transcript from Arcmira".`);
const s = $('Settings').first().json;
// GET /v1/me from "Check the plan's dates". freshness is set on a plan that reads media after a delay, such as the
// Free plan. When this call fails, the run can't tell which dates the plan reads, so it stops rather than guess.
const me = $input.first().json;
if (me.error) {
  const e = refusal(me.error);
  if (e.status === 401) throw keyError();
  throw new Error(`Arcmira didn't answer "Check the plan's dates" after 5 tries (${e.code || e.status || 'error'}). Run the workflow again.`);
}
const delay = Number(me.freshness?.delay_days) || 0;
const ids = [...new Set(String(s.channel_ids || '').split(',').map((id) => id.trim()).filter(Boolean))];
if (!ids.length) throw new Error('Add at least one YouTube channel id (it starts with UC) in "Settings".');
for (const id of ids) if (!/^UC[\w-]{22}$/.test(id)) throw new Error(`Not a YouTube channel id: ${id}. Channel ids start with UC and have 24 characters.`);
const day = 24 * 3600 * 1000;
const iso = (t) => new Date(t).toISOString().replace(/\.\d{3}Z$/, 'Z');
const now = Date.now();
// Arcmira indexes most videos within two days, so the window ends wait_days ago and next week's run picks up the rest.
const before = now - Number(s.wait_days ?? 2) * day;
// On a delayed plan it ends where the plan's results stop, delay_days ago, which falls on served_through. n8n's clock
// sets after and Arcmira's sets the cut, so weeks meet to within the seconds the two clocks differ. before is sent as
// it is. Arcmira cuts a window that runs past the plan's date, and only then does its answer carry the note and unlock link.
const end = delay > 0 ? Math.min(before, now - delay * day) : before;
const after = end - Number(s.days || 7) * day;
const span = `${iso(after).slice(0, 10)} to ${iso(end).slice(0, 10)}`;
return ids.map((id) => ({ json: { channel_id: id, after: iso(after), before: iso(before), span } }));

const refusal = (e) => {
  const msg = String(e.message || '');
  let body = null;
  try { body = JSON.parse(msg.slice(msg.indexOf(' - ') + 3)); if (typeof body === 'string') body = JSON.parse(body); } catch (_) {}
  return { status: Number(e.status || e.httpCode || msg.slice(0, 3)) || 0, code: body?.error?.code || '', text: body?.error?.message || msg, unlock: body?.error?.unlock?.url || '', limit: body?.error?.details?.limit || null };
};
const count = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const keyError = () => new Error(`Arcmira didn't accept the API key. Pick a Header Auth credential named Authorization with the value "Bearer <your key>" in "Check the plan's dates", "List channel videos from Arcmira" and "Get transcript from Arcmira".`);
const asked = $('One item per channel').all().map((i) => i.json);
const span = asked[0].span;
const seen = new Set();
const videos = [];
const missing = [];
const failed = [];
const more = [];
const cut = [];
$input.all().forEach((item, n) => {
  const r = item.json;
  const id = asked[n]?.channel_id || `channel ${n + 1}`;
  if (r.error) {
    const e = refusal(r.error);
    if (e.status === 401) throw keyError();
    // The plan can change between calls, for example when a trial ends, so a list can still be refused for its dates.
    // The digest names that channel.
    if (e.code !== 'freshness_requires_paid' && (e.status === 402 || e.status === 403)) throw new Error(`Arcmira refused the video list (${e.code || e.status}). ${e.text}`);
    failed.push(`${id} (${e.code || e.status || 'error'})`);
    return;
  }
  // On a delayed plan Arcmira cut the window at served_through, and the answer's note says where results stop.
  if (r.freshness) cut.push(r);
  if (!r.indexed_through) { missing.push(id); return; }
  const name = r.channel?.name || id;
  if (r.has_more) more.push(name);
  for (const v of r.episodes || []) {
    if (!v.video_id || seen.has(v.video_id)) continue;
    seen.add(v.video_id);
    videos.push({ video_id: v.video_id, title: v.title || v.video_id, channel: v.channel_name || name });
  }
});
// The digest opens with Arcmira's note, word for word, up to its offer sentence, which becomes the link. From the offer
// on, the note tells agents how to use the list. A channel that had videos in the window carries the plainer note.
const OFFER = 'Open unlock.url to try Pro for free';
const plan = cut.find((r) => r.returned) || cut[0];
const said = String(plan?.note || ''), url = plan?.unlock?.url, at = said.indexOf(OFFER);
const words = at < 0 ? [said.match(/^.*?unlock\.url[^.]*\./)?.[0] || said, url && `unlock.url: <${url}>`] : [said.slice(0, at).trim(), url && `Try Pro for free: <${url}>`];
const lead = plan ? words.filter(Boolean).join(' ') : '';
const note = [
  missing.length ? `_Arcmira doesn't index ${count(missing.length, 'channel')} yet: ${missing.join(', ')}. Ask for ${missing.length === 1 ? 'it' : 'them'} at https://arcmira.com/docs/feedback#help-shape-the-index._` : '',
  failed.length ? `_Arcmira didn't list the videos of ${count(failed.length, 'channel')}: ${failed.join(', ')}._` : '',
  more.length ? `_${more.join(', ')} published more than 25 videos. The digest has the newest 25 of each._` : '',
].filter(Boolean).join('\n');
// A quiet week posts nothing, unless a channel needs your attention.
if (!videos.length) return note ? [{ json: { nothing_new: true, text: [lead, `_No new videos published ${span}._`, note].filter(Boolean).join('\n') } }] : [];
return videos.map((v) => ({ json: { ...v, nothing_new: false, span, note, lead } }));

const refusal = (e) => {
  const msg = String(e.message || '');
  let body = null;
  try { body = JSON.parse(msg.slice(msg.indexOf(' - ') + 3)); if (typeof body === 'string') body = JSON.parse(body); } catch (_) {}
  return { status: Number(e.status || e.httpCode || msg.slice(0, 3)) || 0, code: body?.error?.code || '', text: body?.error?.message || msg, unlock: body?.error?.unlock?.url || '', limit: body?.error?.details?.limit || null };
};
const count = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const keyError = () => new Error(`Arcmira didn't accept the API key. Pick a Header Auth credential named Authorization with the value "Bearer <your key>" in "Check the plan's dates", "List channel videos from Arcmira" and "Get transcript from Arcmira".`);
const videos = $('Keep new videos').all().map((i) => i.json);
const clock = (s) => { s = Math.floor(s); const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
const out = [];
const skipped = [];
$input.all().forEach((item, n) => {
  const t = item.json;
  const v = videos[n] || {};
  // The list carries the video's current title. The transcript keeps the title it was read under.
  const name = v.title || t.video?.title || v.video_id || 'a video';
  if (t.error) {
    const e = refusal(t.error);
    // A wrong key or an account out of credits fails every video, so stop the run where n8n shows it.
    if (e.status === 401 || e.status === 403) throw keyError();
    if (e.status === 402) throw new Error(`Arcmira refused the transcript for credits (${e.code || 402}). ${e.text}`);
    skipped.push(`${name} (${e.code || e.status || 'error'})`);
    return;
  }
  if (t.state !== 'ready' || !Array.isArray(t.lines) || !t.lines.length) { skipped.push(`${name} (${t.state || 'no lines'})`); return; }
  // Premium lines carry a speaker number. Only an identified person's name is passed on.
  const who = new Map((t.speakers || []).filter((p) => p.entity_id).map((p) => [p.id, p.name]));
  let text = '';
  for (const line of t.lines) {
    const row = `[${clock(line.start)}] ${who.has(line.speaker) ? who.get(line.speaker) + ': ' : ''}${line.text}\n`;
    if (text.length + row.length > 200000) { text += '[transcript cut for length]\n'; break; }
    text += row;
  }
  const id = t.video?.id || v.video_id;
  out.push({ video_id: id, title: name, channel: v.channel || t.video?.channel_name, watch_url: t.video?.watch_url || `https://www.youtube.com/watch?v=${id}`, transcript: text });
});
const note = [videos[0]?.note, skipped.length ? `_No transcript for ${count(skipped.length, 'video')}: ${skipped.join(', ')}._` : ''].filter(Boolean).join('\n');
if (!out.length) throw new Error(`Arcmira returned no transcript for the ${count(videos.length, 'new video')}: ${skipped.join(', ')}.`);
return out.map((o) => ({ json: { ...o, span: videos[0].span, note, lead: videos[0].lead } }));

const videos = $('Transcript to timed text').all().map((i) => i.json);
const toSeconds = (c) => c.split(':').map(Number).reduce((a, b) => a * 60 + b, 0);
const parts = $input.all().map((item, n) => {
  const v = videos[n];
  const at = (c) => `<${v.watch_url}${v.watch_url.includes('?') ? '&' : '?'}t=${toSeconds(c)}s|${c}>`;
  const summary = String(item.json.text || '').trim().replace(/\[(\d{1,2}(?::\d{2}){1,2})\]/g, (all, c) => at(c));
  return `*${v.title}* (${v.channel})\n${summary}`;
});
const { span, note, lead } = videos[0];
const footer = `_Transcripts from Arcmira. Each time opens the video at that second._${note ? '\n' + note : ''}`;
// Slack cuts a message at 40,000 characters, so a long week goes out in more than one message.
const messages = [];
let text = `${lead ? lead + '\n' : ''}*New videos from your YouTube channels, published ${span}*`;
for (const part of parts) {
  if (text.length + part.length > 38000) { messages.push(text); text = ''; }
  text += (text ? '\n\n' : '') + part;
}
messages.push(`${text}\n\n${footer}`);
return messages.map((m) => ({ json: { text: m } }));
